function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 1000) return 'grid needs 1 to 1000 rows.';
  const cols = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (cols < 1 || cols > 1000) return 'Each row needs 1 to 1000 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== cols) return 'All rows must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Each cell is 0 or 1.';
  }
  return null;
}

