function numberOfRightTriangles(grid) {
  const ones = [];
  grid.forEach((row, r) => row.forEach((v, c) => { if (v === 1) ones.push([r, c]); }));
  const corner = (a, b, c) => a[0] === b[0] && a[1] === c[1];
  let total = 0;
  for (let i = 0; i < ones.length; i++)
    for (let j = i + 1; j < ones.length; j++)
      for (let k = j + 1; k < ones.length; k++) {
        const [a, b, c] = [ones[i], ones[j], ones[k]];
        if (corner(a, b, c) || corner(a, c, b) || corner(b, a, c) || corner(b, c, a) || corner(c, a, b) || corner(c, b, a)) total++;
      }
  return total;
}

