function generate(rand, size) {
  const rows = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  const cols = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  const density = [0.1, 0.5, 0.9, 1][Math.floor(rand() * 4)];
  const grid = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < density ? 1 : 0)));
  return [grid];
}
